using System.Globalization; using System.Windows; using WPF_SEMANA02.Data; using WPF_SEMANA02.Models;
namespace WPF_SEMANA02.Views;
public partial class IngresosWindow : Window { public IngresosWindow(){InitializeComponent();} private void Guardar_Click(object s,RoutedEventArgs e){if(dpFecha.SelectedDate is null||cmbTipo.SelectedItem is null||string.IsNullOrWhiteSpace(txtTransportista.Text)||!double.TryParse(txtPeso.Text,NumberStyles.Any,CultureInfo.CurrentCulture,out var peso)){MessageBox.Show("Complete los campos y registre un peso válido.","Validación",MessageBoxButton.OK,MessageBoxImage.Warning);return;} AppData.Ingresos.Add(new Ingreso{Fecha=dpFecha.SelectedDate.Value,Peso=peso,TipoVehiculo=((System.Windows.Controls.ComboBoxItem)cmbTipo.SelectedItem).Content.ToString()!,Transportista=txtTransportista.Text.Trim()});MessageBox.Show("Ingreso registrado correctamente.","Información");Limpiar();} private void Limpiar_Click(object s,RoutedEventArgs e)=>Limpiar(); private void Limpiar(){dpFecha.SelectedDate=DateTime.Today;txtPeso.Clear();cmbTipo.SelectedIndex=-1;txtTransportista.Clear();} private void Volver_Click(object s,RoutedEventArgs e)=>Close(); }
